import{_ as t,o as a,c as s,ak as r}from"./chunks/framework.sV-XtlWr.js";const u=JSON.parse('{"title":"Analytics","description":"","frontmatter":{"title":"Analytics","lang":"en-US"},"headers":[],"relativePath":"analytics.md","filePath":"analytics.md","lastUpdated":1786997170000}'),o={name:"analytics.md"};function n(i,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h1><p>Every other view in Piwi answers a question about one project, one run, or one test. The <strong>Analytics</strong> page (<code>/analytics</code>) is the one that steps back: it aggregates every project over a time window you choose, so you can see where the suite as a whole is drifting — and hand a number to someone who doesn&#39;t read stack traces.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>A scope bar at the top sets:</p><ul><li><strong>Period</strong> — last 7 / 30 / 90 days, last year, or all time.</li><li><strong>Environment</strong> — optional; restrict to runs labeled <code>production</code>, <code>staging</code>, … (see <a href="./concepts.html#environment">Environment</a>).</li><li><strong>Full runs only</strong> — exclude partial and interrupted runs, which otherwise skew pass rates.</li></ul><p>Every widget re-aggregates against that scope, and each period is compared against the <em>preceding</em> period of the same length, which is where the &quot;vs previous&quot; deltas come from.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><p><strong>Insights</strong> — an auto-generated, severity-ranked feed of what actually changed: pass-rate drops, failing streaks, stale failure clusters, wasted CI time, oversized timeouts and stale <code>test.slow()</code> marks, regression surges, and slow shared endpoints. Each entry links to the project, run, cluster, or test case behind it. Start here; the rest of the page is the evidence.</p><p><strong>Portfolio health</strong> — one sortable row per project: pass rate and its change vs the previous period, flaky volume, open failure clusters, average run duration, and latest run. Worst health sorts first.</p><p><strong>Pass rate heatmap</strong> — projects × time, colored by daily (or weekly, over longer periods) pass rate. This is the fastest way to answer <em>when</em> something started degrading.</p><p><strong>CI time</strong> and <strong>Wasted CI time</strong> — total minutes your runs consumed, and how many of those produced no signal: time spent inside wait steps plus time spent executing attempts that ended failed or timed out. Because a timed-out test burns its entire (often oversized) budget, the widget also calls out how much is reclaimable by tightening timeouts and removing stale <code>test.slow()</code> marks.</p><p><strong>Flakiest tests</strong> — the global flaky leaderboard, using the same <a href="./flaky-tests.html#impact-ranking">scoring and impact ranking</a> as each project&#39;s Flaky tests tab.</p><p><strong>Failure clusters</strong> — open root causes across all projects by age, occurrences, and error-type mix, with the oldest unresolved cluster highlighted.</p><p><strong>Regression velocity</strong> — new regressions and newly-flaky tests introduced per period, stacked, with the change vs the previous period. Rising bars mean quality debt is accumulating faster than it&#39;s paid down.</p><p><strong>Browser matrix</strong> — pass rate per project × browser, so a suite that&#39;s green on Chromium and failing on WebKit stands out without opening a single run.</p><p><strong>Slow endpoints</strong> — backend calls captured during tests, aggregated across all projects by normalized route: p50/p90 latency, error rate, and how many projects hit each one. A shared endpoint regressing shows up here before it&#39;s obvious in any single suite. Requires the <a href="./capture-fixtures.html">capture fixtures</a>.</p><h2 id="marking-what-you-changed" tabindex="-1">Marking what you changed <a class="header-anchor" href="#marking-what-you-changed" aria-label="Permalink to &quot;Marking what you changed&quot;">​</a></h2><p>Trends are only actionable when you can line them up against events. <a href="./timeline-markers.html">Timeline markers</a> let you record a deploy, a CI-runner migration, or a dependency bump against a project and see it drawn as a vertical line across the trend charts — so &quot;the slowdown started the day we switched runners&quot; becomes something you can see rather than remember.</p><h2 id="how-it-s-built" tabindex="-1">How it&#39;s built <a class="header-anchor" href="#how-it-s-built" aria-label="Permalink to &quot;How it&#39;s built&quot;">​</a></h2><p>Each widget is a registry entry backed by a shared handler and served by one generic endpoint, <code>GET /api/analytics/:widget</code>. The same handlers back the dashboard, the demo, and the API, so a number you read on the page is the number the API returns. Widgets fetch independently, so a slow one never blocks the rest of the page.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./flaky-tests.html">Flaky tests</a> — the per-project analysis these widgets aggregate</li><li><a href="./timeline-markers.html">Timeline markers</a> — annotate the trends with real-world events</li><li><a href="./ui-overview.html#analytics">UI overview</a> — where this sits in the navigation</li></ul>',22)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
